class Solution {
    java.util.Map<String, Integer> memo = new java.util.HashMap<>();
    int X;
    public int leastOpsExpressTarget(int x, int target) {
        X = x;
        return dfs(target, 0) - 1;
    }
    private int dfs(int target, int pos) {
        if (target == 0) return 0;
        if (target == 1) return pos == 0 ? 2 : pos;
        String key = target + "," + pos;
        if (memo.containsKey(key)) return memo.get(key);
        int digit = target % X;
        int rest = target / X;
        int costPer = pos == 0 ? 2 : pos;
        int useCost = digit * costPer + dfs(rest, pos + 1);
        int roundCost = (X - digit) * costPer + dfs(rest + 1, pos + 1);
        int res = Math.min(useCost, roundCost);
        memo.put(key, res);
        return res;
    }
}

class Solution {
    public int leastOpsExpressTarget(int x, int target) {
        int pos = 0;
        int curNoCar = Integer.MAX_VALUE;
        int curCar = Integer.MAX_VALUE;
        int noCar = 0;
        int car = 0;
        while (target > 0) {
            int digit = target % x;
            target /= x;
            int costPer = pos == 0 ? 2 : pos;
            if (pos == 0) {
                noCar = digit * costPer;
                car = (x - digit) * costPer;
            } else {
                int newNoCar = Math.min(noCar + digit * costPer, car + (digit + 1) * costPer);
                int newCar = Math.min(noCar + (x - digit) * costPer, car + (x - digit - 1) * costPer);
                noCar = newNoCar;
                car = newCar;
            }
            pos++;
        }
        return Math.min(noCar, car + pos) - 1;
    }
}
